import { test, expect } from '@playwright/test';

test.describe('Browser Back Button Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com');
    await page.getByRole('link', { name: 'Navigate to Page 1' }).click();
    await page.getByRole('link', { name: 'Navigate to Page 2' }).click();
  });

  test('should maintain app state after using the back button', async ({ page }) => {
    await page.goBack();
    const page1Header = await page.getByText('Page 1 Header');
    await expect(page1Header).toBeVisible();

    await page.goBack();
    const homeHeader = await page.getByText('Home Header');
    await expect(homeHeader).toBeVisible();
  });

  test('should return to Page 2 after going forward', async ({ page }) => {
    await page.goBack();
    await page.goForward();
    const page2Header = await page.getByText('Page 2 Header');
    await expect(page2Header).toBeVisible();
  });
});
